<?php
require __DIR__.'/auth.php'; require_login();
if (!isset($_GET['id']) || !ctype_digit((string)$_GET['id'])) { http_response_code(400); exit('Invalid document'); }
$db=new SQLite3(__DIR__.'/DATABASE/library.db'); $cols=[];$r=$db->query('PRAGMA table_info(Documents)');while($c=$r->fetchArray(SQLITE3_ASSOC))$cols[]=$c['name'];if(!in_array('OWNER_ID',$cols,true)){$db->exec('ALTER TABLE Documents ADD COLUMN OWNER_ID INTEGER NOT NULL DEFAULT 1');}
$q=$db->prepare('SELECT Name, FILE_PATH, FILE_TYPE FROM Documents WHERE Number=:id AND OWNER_ID=:u');$q->bindValue(':id',(int)$_GET['id'],SQLITE3_INTEGER);$q->bindValue(':u',(int)$_SESSION['user_id'],SQLITE3_INTEGER);$doc=$q->execute()->fetchArray(SQLITE3_ASSOC);$root=realpath(__DIR__.'/DATABASE/storage/users/'.(int)$_SESSION['user_id']);$path=$doc?realpath(__DIR__.'/'.$doc['FILE_PATH']):false;if(!$doc||!$root||!$path||strpos($path,$root.DIRECTORY_SEPARATOR)!==0||!is_file($path)){http_response_code(404);exit('Document not found');}header('Content-Type: '.($doc['FILE_TYPE']?:'application/octet-stream'));header('Content-Disposition: inline; filename="'.basename($doc['Name']).'"');header('Content-Length: '.filesize($path));readfile($path);
